"""returns the augmented matrix,
    assuming A is a square matrix"""
def augmented_matrix(A: Any, b: Any) -> object {
    (aug, n) = ([], len(A));
    for i in range(n) {
        t = A[i];
        t.append(b[i]);
        aug.append(t);
    }
    return aug;
}

